// Reference vectors for the Windows engine, generated by the macOS engine itself.
//
// Compiled together with the unchanged Sources/Engine files it exercises (see
// windows/tools/vectors.sh), so whatever these files compute is, by definition,
// what the C++ port has to reproduce.
//
//     vectorgen write DIR      write the .tdv files into DIR
//     vectorgen check DIR      fail when the files in DIR no longer match the Swift code
//     vectorgen selftest DIR   show that check catches a deliberately stale file

import Foundation

// MARK: - Inputs

/// The same 64-bit linear congruential generator tapproof's limittest uses,
/// mapped to roughly ±scale.
struct Noise {
    var seed: UInt64
    mutating func next(scale: Float) -> Float {
        seed = seed &* 6364136223846793005 &+ 1442695040888963407
        return Float(Int64(bitPattern: seed >> 11) - (1 << 52)) / Float(1 << 52) * scale
    }
}

func sine(_ frequency: Double, amplitude: Double, rate: Double, frames: Int, from start: Int = 0) -> [Float] {
    (0..<frames).map { Float(amplitude * sin(2 * .pi * frequency * Double(start + $0) / rate)) }
}

/// Run planar `input` through `process` in blocks, returning the output.
func blocks(_ input: [[Float]], sizes: [Int], process: ([UnsafeMutablePointer<Float>], Int) -> Void) -> [[Float]] {
    let frames = input[0].count
    var output = input
    var start = 0
    var index = 0
    let buffers = input.map { _ in UnsafeMutablePointer<Float>.allocate(capacity: max(1, sizes.max() ?? 1)) }
    defer { buffers.forEach { $0.deallocate() } }
    while start < frames {
        let size = min(sizes[index % sizes.count], frames - start)
        for (channel, buffer) in buffers.enumerated() {
            for i in 0..<size { buffer[i] = input[channel][start + i] }
        }
        process(buffers, size)
        for (channel, buffer) in buffers.enumerated() {
            for i in 0..<size { output[channel][start + i] = buffer[i] }
        }
        start += size
        index += 1
    }
    return output
}

/// The block sizes `blocks` actually used, for the C++ side to repeat.
func usedSizes(frames: Int, sizes: [Int]) -> [Int] {
    var result: [Int] = []
    var start = 0
    while start < frames {
        let size = min(sizes[result.count % sizes.count], frames - start)
        result.append(size)
        start += size
    }
    return result
}

// MARK: - Gain ramp and master volume

func gainRampVectors() -> TDVFile {
    // Each operation either ramps the next `frames` frames to `value`, or
    // resets the ramp to `value`. Zero-length ramps check that an empty block
    // leaves the current gain alone.
    let operations: [(kind: Int32, frames: Int, value: Float)] = [
        (0, 512, 1), (0, 480, 0.5), (0, 0, 0.125), (0, 333, 0.25), (0, 7, 0.25),
        (1, 0, 0.75), (0, 1000, 0), (0, 64, 0), (0, 1, 1), (0, 255, 1),
        (0, 300, 0.3333333), (1, 0, 2), (0, 129, 2), (0, 400, 0.01),
    ]
    let frames = operations.reduce(0) { $0 + $1.frames }
    let rate = 48_000.0
    var noise = Noise(seed: 7)
    let input: [[Float]] = [sine(997, amplitude: 0.8, rate: rate, frames: frames),
                            (0..<frames).map { _ in noise.next(scale: 1) }]
    var output = input
    var ramp = GainRamp(0.6)
    var start = 0
    for operation in operations {
        if operation.kind == 1 {
            ramp.reset(to: operation.value)
            continue
        }
        let left = UnsafeMutablePointer<Float>.allocate(capacity: max(1, operation.frames))
        let right = UnsafeMutablePointer<Float>.allocate(capacity: max(1, operation.frames))
        defer { left.deallocate(); right.deallocate() }
        for i in 0..<operation.frames { left[i] = output[0][start + i]; right[i] = output[1][start + i] }
        ramp.apply(to: [left, right], frameCount: operation.frames, target: operation.value)
        for i in 0..<operation.frames { output[0][start + i] = left[i]; output[1][start + i] = right[i] }
        start += operation.frames
    }

    var file = TDVFile()
    file.add("frames", .i32([Int32(frames)]))
    file.add("initial", .f32([0.6]))
    file.add("opKinds", .i32(operations.map { $0.kind }))
    file.add("opFrames", .i32(operations.map { Int32($0.frames) }))
    file.add("opValues", .f32(operations.map { $0.value }))
    file.add("input", .f32(input.flatMap { $0 }))
    file.add("output", .f32(output.flatMap { $0 }))
    file.add("finalGain", .f32([ramp.current]))
    return file
}

func masterVolumeVectors() -> TDVFile {
    // 0 sets the volume, 1 sets mute (value 1 or 0).
    let operations: [(kind: Int32, value: Float)] = [
        (0, 0.5), (1, 1), (0, 0.25), (1, 0), (0, -3), (0, 1.25), (1, 1), (1, 0), (0, 0), (0, 0.001), (0, 1),
    ]
    let master = MasterVolume()
    var gains: [Float] = [], volumes: [Float] = [], muted: [Int32] = []
    for operation in operations {
        if operation.kind == 0 { master.volume = operation.value } else { master.isMuted = operation.value != 0 }
        gains.append(master.gain)
        volumes.append(master.volume)
        muted.append(master.isMuted ? 1 : 0)
    }
    var file = TDVFile()
    file.add("opKinds", .i32(operations.map { $0.kind }))
    file.add("opValues", .f32(operations.map { $0.value }))
    file.add("gains", .f32(gains))
    file.add("volumes", .f32(volumes))
    file.add("muted", .i32(muted))
    return file
}

// MARK: - Look-ahead limiter

struct LimiterCase {
    var name: String
    var channels: Int
    var sampleRate: Double
    var ceilingDecibels: Double
    var lookaheadSeconds = 0.002
    var releaseSeconds = 0.1
    var sizes: [Int]
    /// Planar input; may have more channels than the limiter, which it must
    /// leave alone.
    var input: [[Float]]
}

func limiterCases() -> [LimiterCase] {
    var noise = Noise(seed: 42)
    var cases: [LimiterCase] = []

    cases.append(LimiterCase(
        name: "tones at +6 and +1.6 dBFS", channels: 2, sampleRate: 48_000, ceilingDecibels: -1, sizes: [512],
        input: [sine(1_000, amplitude: 2, rate: 48_000, frames: 4_800),
                sine(1_500, amplitude: 1.2, rate: 48_000, frames: 4_800)]))

    let burst = (0..<4_410).map { $0 < 1_102 ? Float(0) : Float(4 * sin(2 * .pi * 440 * Double($0) / 44_100)) }
    cases.append(LimiterCase(
        name: "burst from silence, 44.1 kHz, irregular blocks", channels: 2, sampleRate: 44_100, ceilingDecibels: -1,
        sizes: [7, 64, 480, 1_024, 1, 333, 2_048], input: [burst, burst.map { $0 * 0.5 }]))

    cases.append(LimiterCase(
        name: "noise, 96 kHz, mono, longer window", channels: 1, sampleRate: 96_000, ceilingDecibels: -6,
        lookaheadSeconds: 0.005, releaseSeconds: 0.05, sizes: [480],
        input: [(0..<4_800).map { _ in noise.next(scale: 3) }]))

    cases.append(LimiterCase(
        name: "eight channels at different levels", channels: 8, sampleRate: 48_000, ceilingDecibels: -1, sizes: [256],
        input: (0..<8).map { sine(200 * Double($0 + 1), amplitude: 0.25 * Double($0 + 1), rate: 48_000, frames: 2_400) }))

    cases.append(LimiterCase(
        name: "a channel beyond the limiter's passes untouched", channels: 2, sampleRate: 48_000, ceilingDecibels: -1,
        sizes: [512],
        input: [sine(300, amplitude: 1.5, rate: 48_000, frames: 2_400),
                sine(450, amplitude: 0.5, rate: 48_000, frames: 2_400),
                (0..<2_400).map { _ in noise.next(scale: 5) }]))

    let spikes = (0..<2_400).map { $0 % 300 == 150 ? Float(3) : Float(0.1 * sin(Double($0) / 7)) }
    cases.append(LimiterCase(
        name: "a one-sample window has no delay", channels: 2, sampleRate: 48_000, ceilingDecibels: -1,
        lookaheadSeconds: 0.000_01, sizes: [100], input: [spikes, spikes.map { -$0 }]))
    return cases
}

func lookaheadVectors() -> TDVFile {
    var file = TDVFile()
    let cases = limiterCases()
    file.add("cases", .i32([Int32(cases.count)]))
    for (index, limiterCase) in cases.enumerated() {
        let ceiling = pow(10, limiterCase.ceilingDecibels / 20)
        let limiter = LookaheadLimiter(channels: limiterCase.channels, sampleRate: limiterCase.sampleRate,
                                       ceiling: ceiling, lookaheadSeconds: limiterCase.lookaheadSeconds,
                                       releaseSeconds: limiterCase.releaseSeconds)
        var lowest: [Double] = []
        let output = blocks(limiterCase.input, sizes: limiterCase.sizes) { channels, size in
            lowest.append(limiter.process(channels, frameCount: size))
        }
        let prefix = "case\(index)."
        file.add(prefix + "name", .text(limiterCase.name))
        file.add(prefix + "channels", .i32([Int32(limiterCase.channels)]))
        file.add(prefix + "inputChannels", .i32([Int32(limiterCase.input.count)]))
        file.add(prefix + "frames", .i32([Int32(limiterCase.input[0].count)]))
        file.add(prefix + "sampleRate", .f64([limiterCase.sampleRate]))
        file.add(prefix + "ceiling", .f64([ceiling]))
        file.add(prefix + "lookaheadSeconds", .f64([limiterCase.lookaheadSeconds]))
        file.add(prefix + "releaseSeconds", .f64([limiterCase.releaseSeconds]))
        file.add(prefix + "blocks", .i32(usedSizes(frames: limiterCase.input[0].count, sizes: limiterCase.sizes).map { Int32($0) }))
        file.add(prefix + "latency", .i32([Int32(limiter.latencyFrames)]))
        file.add(prefix + "input", .f32(limiterCase.input.flatMap { $0 }))
        file.add(prefix + "output", .f32(output.flatMap { $0 }))
        file.add(prefix + "lowest", .f64(lowest))
    }
    return file
}

// MARK: - Routing graph

func routingGraphVectors() -> TDVFile {
    // Each connect call is "inputs>outputs" with comma-separated devices;
    // calls are separated by ';'. The expected route is comma-separated, or
    // empty for no loop.
    let cases: [(name: String, connects: String)] = [
        ("mic -> Tapdeck", "mic>Tapdeck"),
        ("Tapdeck -> Tapdeck (same mix)", "Tapdeck>Tapdeck,speakers"),
        ("Tapdeck -> speakers (listen)", "Tapdeck>speakers"),
        ("A -> B, B -> A (two mixes)", "Streaming>Meetings;Meetings>Streaming"),
        ("A -> B -> C (chain)", "A>B;B>C"),
        ("A -> B -> C -> A (three mixes)", "A>B;B>C;C>A"),
        ("app sources only (no device edges)", ">Tapdeck"),
        ("an input with no outputs is still a node", "A>;B>A"),
        ("two loops: the first in sorted order wins", "C>D;D>C;A>B;B>A"),
        ("a loop found from a later start", "A>B;B>C;C>B"),
        ("neighbours are tried in sorted order", "S>B,A;A>S;B>S"),
        ("several inputs in one mix", "mic,line>cable;cable>mic"),
        ("names outside ASCII", "麦克风>扬声器;Lautsprecher>麦克风;扬声器>Lautsprecher"),
    ]
    var file = TDVFile()
    file.add("cases", .i32([Int32(cases.count)]))
    for (index, graphCase) in cases.enumerated() {
        var graph = RoutingGraph()
        for call in graphCase.connects.split(separator: ";", omittingEmptySubsequences: false) {
            let sides = call.split(separator: ">", omittingEmptySubsequences: false)
            let inputs = sides[0].split(separator: ",").map(String.init)
            let outputs = sides[1].split(separator: ",").map(String.init)
            graph.connect(from: inputs, to: outputs)
        }
        let prefix = "case\(index)."
        file.add(prefix + "name", .text(graphCase.name))
        file.add(prefix + "connects", .text(graphCase.connects))
        file.add(prefix + "cycle", .text(graph.firstCycle()?.joined(separator: ",") ?? ""))
    }
    return file
}

// MARK: - Running

let generators: [(file: String, make: () -> TDVFile)] = [
    ("gainramp.tdv", gainRampVectors),
    ("mastervolume.tdv", masterVolumeVectors),
    ("lookahead.tdv", lookaheadVectors),
    ("routinggraph.tdv", routingGraphVectors),
]

/// Compare a regenerated file with a stored one. Audio may differ by what
/// another macOS version's math library rounds differently; everything else
/// must match exactly.
func differences(_ fresh: TDVFile, _ stored: TDVFile) -> [String] {
    var problems: [String] = []
    let freshNames = fresh.entries.map { $0.name }, storedNames = stored.entries.map { $0.name }
    if freshNames != storedNames { problems.append("entries differ") }
    for (name, value) in fresh.entries {
        guard let other = stored.entries.first(where: { $0.name == name })?.value else { continue }
        switch (value, other) {
        case let (.f32(a), .f32(b)):
            if a.count != b.count { problems.append("\(name): \(b.count) values, expected \(a.count)"); continue }
            let worst = zip(a, b).map { abs(Double($0) - Double($1)) }.max() ?? 0
            if !(worst <= 1e-6) { problems.append("\(name): differs by up to \(worst)") }
        case let (.f64(a), .f64(b)):
            if a.count != b.count { problems.append("\(name): \(b.count) values, expected \(a.count)"); continue }
            let worst = zip(a, b).map { abs($0 - $1) }.max() ?? 0
            if !(worst <= 1e-9) { problems.append("\(name): differs by up to \(worst)") }
        default:
            if value != other { problems.append("\(name): differs") }
        }
    }
    return problems
}

func check(_ directory: URL, files: [String: TDVFile]? = nil) -> Bool {
    var clean = true
    for generator in generators {
        let fresh = generator.make()
        let stored: TDVFile
        do {
            stored = try files?[generator.file]
                ?? TDVFile.decode(Data(contentsOf: directory.appendingPathComponent(generator.file)))
        } catch {
            print("STALE  \(generator.file): \(error)")
            clean = false
            continue
        }
        let problems = differences(fresh, stored)
        print("\(problems.isEmpty ? "OK   " : "STALE")  \(generator.file)\(problems.isEmpty ? "" : ": " + problems.joined(separator: "; "))")
        if !problems.isEmpty { clean = false }
    }
    return clean
}

let arguments = CommandLine.arguments
guard arguments.count == 3, ["write", "check", "selftest"].contains(arguments[1]) else {
    print("usage: vectorgen write|check|selftest DIR")
    exit(2)
}
let directory = URL(fileURLWithPath: arguments[2], isDirectory: true)

switch arguments[1] {
case "write":
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    for generator in generators {
        try generator.make().encoded().write(to: directory.appendingPathComponent(generator.file))
        print("wrote \(generator.file)")
    }

case "check":
    if !check(directory) {
        print("The reference vectors no longer match the Swift code: run windows/tools/vectors.sh write,")
        print("then bring the C++ port in line until vectortest passes.")
        exit(1)
    }

default: // selftest
    // A stored output nudged by 0.001 must be reported as stale.
    var stale = gainRampVectors()
    if let index = stale.entries.firstIndex(where: { $0.name == "output" }), case .f32(var values) = stale.entries[index].value {
        values[values.count / 2] += 0.001
        stale.entries[index].value = .f32(values)
    }
    print("Checking a deliberately stale gainramp.tdv:")
    let caught = !check(directory, files: ["gainramp.tdv": stale])
    print(caught ? "selftest passed: the stale vector was caught" : "selftest FAILED: the stale vector went unnoticed")
    exit(caught ? 0 : 1)
}
